using System;using System.Linq;using System.Runtime.CompilerServices;using System.Windows.Forms;
namespace BeamScheduleFormatter {
static class TopTabLayout {
 static readonly ConditionalWeakTable<Control,object> hooked=new ConditionalWeakTable<Control,object>();
 internal static void AttachCommands(TabControl root,Control commands,Form owner){Action move=null;Action<Control> hook=null;/* the commands common to the whole tab group sit right above its tabs (owner, 27 November 2026: "yung mga button na common per group tabbed
    ilipat sa taas nila para maayos"), not inside the innermost page */
  move=()=>{if(root.IsDisposed)return;var host=root.Parent;if(host==null)return;if(commands.Parent!=host)host.Controls.Add(commands);commands.Dock=DockStyle.Top;/* docking runs from the last child: the tabs fill what is left, the commands dock just above them */if(root.Dock==DockStyle.Fill){host.Controls.SetChildIndex(root,0);host.Controls.SetChildIndex(commands,1);}};hook=control=>{object old;if(hooked.TryGetValue(control,out old))return;hooked.Add(control,new object());var tabs=control as TabControl;if(tabs!=null){ModernUi.Navigation(tabs);tabs.SelectedIndexChanged+=(s,e)=>move();}foreach(Control child in control.Controls)hook(child);control.ControlAdded+=(s,e)=>hook(e.Control);};hook(root);owner.Shown+=(s,e)=>move();move();}
 internal static void Promote(Form owner,TabControl tabs,Control input,Control oldHost,Control commands,string caption,Control note=null){owner.SuspendLayout();try{if(oldHost!=null&&oldHost!=tabs){oldHost.Controls.Remove(tabs);owner.Controls.Remove(oldHost);oldHost.Dispose();}else owner.Controls.Remove(tabs);owner.Controls.Remove(input);var page=new TabPage(caption);input.Dock=DockStyle.Fill;page.Controls.Add(input);if(note!=null){owner.Controls.Remove(note);note.Dock=DockStyle.Top;page.Controls.Add(note);}var rest=tabs.TabPages.Cast<TabPage>().ToList();tabs.TabPages.Clear();tabs.TabPages.Add(page);foreach(var p in rest)tabs.TabPages.Add(p);tabs.Dock=DockStyle.Fill;owner.Controls.Add(tabs);owner.Controls.SetChildIndex(tabs,0);tabs.SelectedTab=page;AttachCommands(tabs,commands,owner);}finally{owner.ResumeLayout(true);}}
}
}
